def load_config(path):
    cfg = read_json(path)
    unknown = set(cfg) - set(DEFAULT)
    if unknown:
        raise ValueError("Chiavi configurazione sconosciute: " + str(sorted(unknown)))
    if set(cfg.get("export", {})) - set(DEFAULT["export"]):
        raise ValueError("Chiavi export sconosciute; non inserire password nel file di configurazione")
    cfg = {**DEFAULT, **cfg, "export": {**DEFAULT["export"], **cfg.get("export", {})}}
    for name in ("inventory_seconds", "rescan_seconds", "retry_seconds", "scanner_timeout_seconds",
                 "worker_timeout_seconds", "stop_grace_seconds", "max_concurrent_scans", "max_queue"):
        if isinstance(cfg[name], bool) or not isinstance(cfg[name], (int, float)) or not math.isfinite(cfg[name]) or cfg[name] <= 0:
            raise ValueError("Valore positivo richiesto: " + name)
    for name in ("max_concurrent_scans", "max_queue", "scanner_timeout_seconds"):
        if not isinstance(cfg[name], int):
            raise ValueError("Intero richiesto: " + name)
    if cfg["max_concurrent_scans"] > 8 or cfg["scanner_timeout_seconds"] > 120:
        raise ValueError("Massimo 8 scansioni concorrenti e timeout scanner <=120 secondi")
    if cfg["worker_timeout_seconds"] <= cfg["scanner_timeout_seconds"] + 5:
        raise ValueError("worker_timeout_seconds deve superare il timeout scanner di almeno 5 secondi")
    if isinstance(cfg["max_session_minutes"], bool) or not math.isfinite(cfg["max_session_minutes"]) or cfg["max_session_minutes"] < 0:
        raise ValueError("max_session_minutes non puo essere negativo")
    if isinstance(cfg["baseline_seconds"], bool) or not isinstance(cfg["baseline_seconds"], (int,float)) or not math.isfinite(cfg["baseline_seconds"]) or cfg["baseline_seconds"] < 0:
        raise ValueError("baseline_seconds deve essere finito e non negativo")
    ec = cfg["export"]
    if not isinstance(ec["request_timeout_seconds"], (int, float)) or ec["request_timeout_seconds"] <= 0:
        raise ValueError("export.request_timeout_seconds deve essere positivo")
    for key in ("new_process_watch_seconds", "new_process_rescan_seconds", "priority_burst"):
        value = cfg[key]
        if isinstance(value, bool) or not isinstance(value, int) or value <= 0:
            raise ValueError(key + " deve essere un intero positivo")
    if cfg["new_process_rescan_seconds"] > cfg["new_process_watch_seconds"]:
        raise ValueError("Intervallo di ricontrollo maggiore della finestra iniziale")
    if not cfg["targets"]:
        raise ValueError("Configurare almeno un target di integrita")
    for target in cfg["targets"]:
        if (not re.match(r"^[A-Za-z]:\\", target.get("Module", "")) or
                not target.get("Function") or
                not re.fullmatch(r"T\d{4}\.\d{3}", target.get("TechniqueId", ""))):
            raise ValueError("Target di integrita non valido")
    base = Path(path).resolve().parent
    if cfg["sensor_mode"] not in ("both", "pe-sieve", "moneta"):
        raise ValueError("sensor_mode deve essere both, pe-sieve oppure moneta")
    for key in ("output_root", "pe_sieve_path", "moneta_path", "telemetry_path"):
        cfg[key] = str((base / Path(cfg[key])).resolve())
    if cfg["export"]["ca_file"]:
        cfg["export"]["ca_file"] = str((base / cfg["export"]["ca_file"]).resolve())
    if cfg["export"]["ssh_identity_file"]:
        cfg["export"]["ssh_identity_file"] = str((base / cfg["export"]["ssh_identity_file"]).resolve())
    if cfg["export"]["transport"] not in ("ssh", "indexer"):
        raise ValueError("export.transport deve essere ssh oppure indexer")
    return cfg


WORKER = r'''param([Parameter(Mandatory=$true)][string]$SettingsPath)
$ErrorActionPreference = 'Stop'
try {
    $s = Get-Content -LiteralPath $SettingsPath -Raw | ConvertFrom-Json
    $deadline = [DateTime]::UtcNow.AddSeconds(20)
    while (-not (Test-Path -LiteralPath $s.Gate)) {
        if ([DateTime]::UtcNow -gt $deadline) { throw 'PARENT_GATE_TIMEOUT' }
        Start-Sleep -Milliseconds 50
    }
    $additional = @()
    for ($i=1; $i -lt $s.Targets.Count; $i++) {
        $t = $s.Targets[$i]
        $additional += @{Module=[string]$t.Module; Function=[string]$t.Function; TechniqueId=[string]$t.TechniqueId}
    }
    $primary = $s.Targets[0]
    $p = @{
        TargetPid=[int]$s.TargetPid; TargetModule=[string]$primary.Module
        TargetFunction=[string]$primary.Function; TechniqueId=[string]$primary.TechniqueId
        PeSievePath=[string]$s.PeSievePath; OutputLog=[string]$s.OutputLog
        WorkRoot=[string]$s.WorkRoot; RunId=[string]$s.RunId
        ResultPath=[string]$s.ResultPath; TimeoutSeconds=[int]$s.TimeoutSeconds
        ReadinessTimeoutMilliseconds=0; ExpectedProcessStartUTC=[string]$s.ExpectedProcessStartUTC
        AdditionalTargets=$additional
    }
    if ($s.SensorKind -eq 'moneta') {
        [void]$p.Remove('PeSievePath')
        [void]$p.Remove('AdditionalTargets')
        [void]$p.Remove('ReadinessTimeoutMilliseconds')
        $p.MonetaPath = [string]$s.MonetaPath
    }
    & $s.SensorPath @p | Out-Null
    if (-not (Test-Path -LiteralPath $s.ResultPath)) { throw 'SENSOR_RESULT_MISSING' }
    exit 0
} catch {
    [Console]::Error.WriteLine($_.Exception.Message)
    exit 2
}
'''


class Windows:
    """Read-only process inventory and Job Objects for OUR scanner workers only."""
    def __init__(self):
        if os.name != "nt":
            raise RuntimeError("Il monitoraggio richiede Windows; esportazione disponibile anche altrove")
        self.k = ctypes.WinDLL("kernel32", use_last_error=True)
        class ProcessEntry(ctypes.Structure):
            _fields_ = [("dwSize", wt.DWORD), ("cntUsage", wt.DWORD), ("pid", wt.DWORD),
                        ("heap", ctypes.c_size_t), ("module", wt.DWORD), ("threads", wt.DWORD),
                        ("parent", wt.DWORD), ("priority", wt.LONG), ("flags", wt.DWORD),
                        ("image", wt.WCHAR * 260)]
        self.Entry = ProcessEntry
        signatures = {
            "CreateToolhelp32Snapshot": ([wt.DWORD, wt.DWORD], wt.HANDLE),
            "Process32FirstW": ([wt.HANDLE, ctypes.POINTER(ProcessEntry)], wt.BOOL),
            "Process32NextW": ([wt.HANDLE, ctypes.POINTER(ProcessEntry)], wt.BOOL),
            "OpenProcess": ([wt.DWORD, wt.BOOL, wt.DWORD], wt.HANDLE),
            "CloseHandle": ([wt.HANDLE], wt.BOOL),
            "GetProcessTimes": ([wt.HANDLE] + [ctypes.POINTER(wt.FILETIME)] * 4, wt.BOOL),
            "QueryFullProcessImageNameW": ([wt.HANDLE, wt.DWORD, wt.LPWSTR, ctypes.POINTER(wt.DWORD)], wt.BOOL),
            "CreateJobObjectW": ([ctypes.c_void_p, wt.LPCWSTR], wt.HANDLE),
            "SetInformationJobObject": ([wt.HANDLE, ctypes.c_int, ctypes.c_void_p, wt.DWORD], wt.BOOL),
            "AssignProcessToJobObject": ([wt.HANDLE, wt.HANDLE], wt.BOOL)
        }
        for name, (args, result) in signatures.items():
            f = getattr(self.k, name); f.argtypes = args; f.restype = result

    def identity(self, pid):
        handle = self.k.OpenProcess(0x1000, False, pid)
        if not handle:
            return None, ctypes.get_last_error()
        try:
            c, e, k, u = (wt.FILETIME() for _ in range(4))
            if not self.k.GetProcessTimes(handle, ctypes.byref(c), ctypes.byref(e), ctypes.byref(k), ctypes.byref(u)):
                return None, ctypes.get_last_error()
            ticks = (c.dwHighDateTime << 32) | c.dwLowDateTime
            sec, rest = divmod(ticks, 10_000_000)
            dt = datetime(1601, 1, 1, tzinfo=UTC) + timedelta(seconds=sec)
            iso = dt.strftime("%Y-%m-%dT%H:%M:%S") + ".%07dZ" % rest
            buf, size = ctypes.create_unicode_buffer(32768), wt.DWORD(32768)
            image = buf.value if self.k.QueryFullProcessImageNameW(handle, 0, buf, ctypes.byref(size)) else None
            if image is not None:
                image = buf.value
            return {"pid": pid, "creation_ticks": ticks, "process_start_utc": iso, "image": image}, 0
        finally:
            self.k.CloseHandle(handle)

    def inventory(self):
        snap = self.k.CreateToolhelp32Snapshot(2, 0)
        if snap == ctypes.c_void_p(-1).value:
            raise ctypes.WinError(ctypes.get_last_error())
        try:
            entry = self.Entry(); entry.dwSize = ctypes.sizeof(entry)
            found = self.k.Process32FirstW(snap, ctypes.byref(entry))
            if not found:
                raise ctypes.WinError(ctypes.get_last_error())
            result = {}
            while found:
                row, err = self.identity(int(entry.pid))
                if row is None:
                    row = {"pid": int(entry.pid), "creation_ticks": None, "identity_error": err}
                row["name"] = entry.image
                row["parent_pid"] = int(entry.parent)
                result[row["pid"]] = row
                found = self.k.Process32NextW(snap, ctypes.byref(entry))
            err = ctypes.get_last_error()
            if err not in (0, 18):
                raise ctypes.WinError(err)
            return result
        finally:
            self.k.CloseHandle(snap)

    def job(self, proc):
        class Basic(ctypes.Structure):
            _fields_ = [("p", ctypes.c_int64), ("j", ctypes.c_int64), ("flags", wt.DWORD),
                        ("min", ctypes.c_size_t), ("max", ctypes.c_size_t), ("active", wt.DWORD),
                        ("affinity", ctypes.c_size_t), ("priority", wt.DWORD), ("scheduling", wt.DWORD)]
        class Extended(ctypes.Structure):
            _fields_ = [("basic", Basic), ("io", ctypes.c_uint64 * 6),
                        ("process_mem", ctypes.c_size_t), ("job_mem", ctypes.c_size_t),
                        ("peak_process", ctypes.c_size_t), ("peak_job", ctypes.c_size_t)]
        h = self.k.CreateJobObjectW(None, None)
        if not h:
            raise ctypes.WinError(ctypes.get_last_error())
        limits = Extended(); limits.basic.flags = 0x2000  # KILL_ON_JOB_CLOSE
        if (not self.k.SetInformationJobObject(h, 9, ctypes.byref(limits), ctypes.sizeof(limits)) or
                not self.k.AssignProcessToJobObject(h, int(proc._handle))):
            err = ctypes.get_last_error(); self.k.CloseHandle(h)
            raise ctypes.WinError(err)
        return h


def sensor_sha256_for_mode(sensor_mode):
    """Return the actual source hash for the selected memory sensor.

    Keep metadata tied to the exact script shipped with the GNS3 package.
    """
    if sensor_mode == "pe-sieve":
        return SENSOR_SHA256
    if sensor_mode == "moneta":
        sensor_path = Path(__file__).parent / "sensors" / "Invoke-MonetaMemorySensor.ps1"
        return hashlib.sha256(sensor_path.read_bytes()).hexdigest()
    raise ValueError("Unsupported sensor_mode: " + str(sensor_mode))


def materialize_assets(session, sensor_mode):
    asset = session / "assets"; asset.mkdir()
    # Ship the benchmark sensor/normalizer explicitly, while preserving single-file fallback.
    external = Path(__file__).parent / "sensors" / "Invoke-MemoryIntegritySensor.ps1"
    sensor = external.read_bytes() if external.is_file() else base64.b64decode(SENSOR_B64)
    if hashlib.sha256(sensor).hexdigest() != SENSOR_SHA256:
        raise ValueError("Checksum del sensore/normalizzatore non valido: usare la versione inclusa nel pacchetto")
    (asset / "Invoke-MemoryIntegritySensor.ps1").write_bytes(sensor)
    # Moneta is a distinct, audited sensor with no embedded fallback.
    # Never silently use PE-sieve when a Moneta session was requested.
    if sensor_mode in ("both", "moneta"):
        moneta = Path(__file__).parent / "sensors" / "Invoke-MonetaMemorySensor.ps1"
        if not moneta.is_file():
            raise FileNotFoundError("Moneta sensor missing in sensors/ next to orchestratore_hr_gns3.py")
        moneta_bytes = moneta.read_bytes()
        if hashlib.sha256(moneta_bytes).hexdigest() != MONETA_SENSOR_SHA256:
            raise ValueError("Checksum del sensore Moneta non valido")
        (asset / moneta.name).write_bytes(moneta_bytes)
    (asset / "worker.ps1").write_text(WORKER, encoding="utf-8-sig")
    return asset


def result_observations(data):
    observations = data.get("observations") if isinstance(data, dict) else None
    return observations if isinstance(observations, list) else [data]


def active_sensors(cfg):
    mode = cfg["sensor_mode"]
    if mode == "both":
        return ("pe-sieve", "moneta")
    if mode in ("pe-sieve", "moneta"):
        return (mode,)
    raise ValueError("sensor_mode deve essere both, pe-sieve oppure moneta")


def memory_detection_class(ob):
    """Route generic target findings away from already covered AMSI/ETW rules.

    This labels evidence, not malware or RAT attribution. Original fields remain
    unchanged. The added 100510 requires GENERIC_TARGET; original rules do not.
    """
    def true(name):
        return ob.get(name) is True
    def path(name):
        return str(ob.get(name) or "").replace("/", "\\").casefold()
    if ob.get("sensor") == "moneta":
        return "MONETA_IOC" if true("scan_completed") and ob.get("status") == "SCANNED_SUSPICIOUS" else "DIAGNOSTIC"
    if ob.get("sensor") != "pe-sieve":
        return "DIAGNOSTIC"
    if true("module_modified") and true("amsi_modified"):
        return "AMSI"  # Existing chain 100410 -> 100411 -> possibly 100412.
    etw = (
        true("module_modified") and true("target_scan_completed") and true("target_integrity_verified")
        and path("target_module") == r"c:\windows\system32\ntdll.dll"
        and path("module") == r"c:\windows\system32\ntdll.dll"
        and ob.get("target_function") == "NtTraceEvent"
        and ob.get("target_technique_id") == "T1562.006"
        and true("target_module_modified")
        and isinstance(ob.get("patch_count"), int) and not isinstance(ob.get("patch_count"), bool)
        and ob["patch_count"] > 0
    )
    if etw:
        return "ETW"  # Existing chain 100420 -> possibly 100421.
    if (true("module_modified") and true("target_scan_completed") and true("target_module_modified")
            and ob.get("generic_status") in ("SCANNED_TARGET_MODULE_MODIFIED", "SCANNED_TARGET_FUNCTION_PATCHED")):
        return "GENERIC_TARGET"
    return "DIAGNOSTIC"


SCRIPT_HOSTS = frozenset(("powershell.exe", "pwsh.exe", "cmd.exe", "wscript.exe",
                          "cscript.exe", "mshta.exe", "rundll32.exe", "regsvr32.exe"))


class Monitor:
    def __init__(self, cfg, session, native):
        self.cfg, self.session, self.native = cfg, session, native
        self.modes = active_sensors(cfg)
        self.asset = materialize_assets(session, cfg["sensor_mode"])
        self.telemetry = session / "monitoraggio" / "eventi_memoria.jsonl"
        self.known, self.pending, self.running = {}, {}, {}
        self.coverage = {}
        self.counts = collections.Counter()
        self.sensor_counts = {kind: collections.Counter() for kind in self.modes}
        self.seq = 0
        self.command_buffer = ""
        self.next_inventory = 0.0
        self.first_inventory = True
        self.new_streak = 0
        self.phase = "BASELINE" if cfg["baseline_seconds"] else "OBSERVATION"
        self.baseline_end_utc = None
        self.runtime = {}
        self.ps = str(Path(os.environ.get("SystemRoot", r"C:\Windows")) / "System32/WindowsPowerShell/v1.0/powershell.exe")

    def preflight(self):
        if len(str(self.session)) > 100:
            raise ValueError("Percorso sessione troppo lungo per gli scanner: impostare output_root=C:\\GNS3Runs e session_prefix breve")
        probe = self.asset / "preflight.ps1"
        def quote(value):
            return "'" + str(value).replace("'", "''") + "'"
        target=self.cfg["targets"][0]
        script="$ErrorActionPreference='Stop'\nAdd-Type -TypeDefinition 'public static class HRPreflightProbe {}'\n"
        for kind in self.modes:
            name="Invoke-MonetaMemorySensor.ps1" if kind=="moneta" else "Invoke-MemoryIntegritySensor.ps1"
            script += ". " + quote(self.asset/name) + " -TargetPid 1234 -TargetModule " + quote(target["Module"]) + " -TargetFunction " + quote(target["Function"]) + " -TechniqueId " + quote(target["TechniqueId"]) + "\n"
            if kind=="moneta":
                script += "$probeOb=New-MonetaObservation -ProcessId 1234 -Run 'preflight'\n"
            else:
                script += "$probeOb=New-MemoryObservation -ProcessId 1234 -RunIdentifier 'preflight'\n"
            script += "if ($probeOb.pid -ne 1234) { throw 'OBSERVATION_FACTORY_FAILED' }\n"
        script += "[Console]::WriteLine('HR_PREFLIGHT_OK')\n"
        probe.write_text(script, encoding="utf-8-sig")
        with (self.session / "powershell_preflight.txt").open("wb") as out:
            proc = subprocess.run([self.ps, "-NoLogo", "-NoProfile", "-NonInteractive", "-File", str(probe)],
                                  stdin=subprocess.DEVNULL, stdout=out, stderr=subprocess.STDOUT,
                                  creationflags=subprocess.CREATE_NO_WINDOW, timeout=30)
        if proc.returncode != 0 or b"HR_PREFLIGHT_OK" not in (self.session / "powershell_preflight.txt").read_bytes():
            raise RuntimeError("PowerShell non consente script/helper richiesti. Vedere powershell_preflight.txt; usare le policy autorizzate del laboratorio")

    def log(self, event, **data):
        append_json(self.session / "monitoraggio" / "scansioni.jsonl", {"timestamp": now(), "event": event, **data})
        self.counts[event] += 1
        if data.get("sensor") in self.sensor_counts:
            self.sensor_counts[data["sensor"]][event] += 1

    def register_runtime(self, row, role, sensor=None):
        if row.get("creation_ticks") is None:
            return
        key = (row["pid"], row["creation_ticks"])
        if key not in self.runtime:
            record = {"pid":row["pid"], "creation_ticks":row["creation_ticks"],
                      "start_utc":row["process_start_utc"], "end_utc":None,
                      "role":role, "sensor":sensor, "image":row.get("image"), "name":row.get("name")}
            self.runtime[key] = record
            append_json(self.session / "monitoraggio" / "processi_sensore.jsonl", {"event":"START", **record})

    def close_runtime(self, pid, creation_ticks=None):
        for key, record in self.runtime.items():
            if key[0] == pid and (creation_ticks is None or key[1] == creation_ticks) and not record["end_utc"]:
                record["end_utc"] = now()
                append_json(self.session / "monitoraggio" / "processi_sensore.jsonl", {"event":"END", **record})

    def refresh(self):
        present = self.native.inventory()
        current = time.monotonic()
        active_worker_pids = {int(w["proc"].pid):w["kind"] for w in self.running.values()}
        own = {os.getpid(), *active_worker_pids}
        # Identify actual scanner/helper descendants, not every executable with that name.
        changed = True
        while changed:
            changed = False
            for pid, row in present.items():
                if pid not in own and row.get("parent_pid") in own and row.get("parent_pid") != os.getpid():
                    own.add(pid); changed = True
        for pid in own:
            row = present.get(pid)
            if row and row.get("creation_ticks") is not None:
                role = "ORCHESTRATOR" if pid == os.getpid() else ("WORKER" if pid in active_worker_pids else "SCANNER_OR_HELPER")
                self.register_runtime(row, role, active_worker_pids.get(pid))
        for key in list(self.runtime):
            if key[0] not in present or present[key[0]].get("creation_ticks") != key[1]:
                self.close_runtime(*key)
        excluded = {str(n).casefold() for n in self.cfg["excluded_image_names"]}
        valid = {}
        for pid, row in present.items():
            if pid in (0, 4) or pid in own:
                continue
            if row["name"].casefold() in excluded:
                self.log_once_identity(pid, row, "EXCLUDED_BY_CONFIGURATION"); continue
            if row["creation_ticks"] is None:
                self.log_once_identity(pid, row, "IDENTITY_UNAVAILABLE"); continue
            key = (pid, row["creation_ticks"])
            previous = self.known.get(key)
            row["due_by_sensor"] = previous["due_by_sensor"] if previous else {s:current for s in self.modes}
            row["priority_by_sensor"] = previous["priority_by_sensor"] if previous else {s:(1 if self.first_inventory else 0) for s in self.modes}
            row["discovered_after_initial"] = previous["discovered_after_initial"] if previous else not self.first_inventory
            row["discovered_monotonic"] = previous["discovered_monotonic"] if previous else current
            row["discovered_utc"] = previous["discovered_utc"] if previous else now()
            row["script_host"] = previous["script_host"] if previous else row["name"].casefold() in SCRIPT_HOSTS
            # Recheck new processes / existing script hosts shortly after the first scan.
            row["watch_until"] = previous["watch_until"] if previous else (
                current + self.cfg["new_process_watch_seconds"]
                if row["discovered_after_initial"] or row["script_host"] else current)
            valid[key] = row
            if key not in self.coverage:
                self.coverage[key] = {"pid":pid, "creation_ticks":key[1], "process_start_utc":row["process_start_utc"],
                                      "image":row.get("image"), "name":row["name"], "sensors":{s:{"attempted":0,"completed":0,"errors":0,"completed_by_phase":{"BASELINE":0,"OBSERVATION":0}} for s in self.modes}}
                self.log("PROCESS_OBSERVED", pid=pid, creation_ticks=key[1], name=row["name"])
        for task, row in list(self.pending.items()):
            if task[:2] not in valid:
                self.log("TERMINATED_BEFORE_SCAN", pid=task[0], creation_ticks=task[1], sensor=task[2])
                del self.pending[task]
        self.known = valid
        self.first_inventory = False
        for key, row in valid.items():
            for kind in self.modes:
                task = (*key, kind)
                if row["due_by_sensor"][kind] <= current and task not in self.running and task not in self.pending:
                    if len(self.pending) >= self.cfg["max_queue"]:
                        self.log("QUEUE_FULL", pid=key[0], sensor=kind); continue
                    self.pending[task] = {**row, "kind":kind, "due":row["due_by_sensor"][kind],
                                          "priority":row["priority_by_sensor"][kind]}

    def log_once_identity(self, pid, row, event):
        previous = getattr(self, "identity_messages", {})
        signature = (row.get("creation_ticks"), row.get("identity_error"), event)
        if previous.get(pid) != signature:
            self.log(event, pid=pid, name=row["name"], error=row.get("identity_error"))
            previous[pid] = signature
        self.identity_messages = previous if len(previous) <= 8192 else {pid:signature}

    def discard_pending_identity(self, identity, reason):
        # Running workers keep their immutable identity and historical coverage.
        # Only unstarted work for this PID+creation time is invalidated.
        self.known.pop(identity, None)
        for queued in list(self.pending):
            if queued[:2] == identity:
                self.pending.pop(queued)
                self.log("NOT_SCANNED_IDENTITY_INVALIDATED",pid=queued[0],creation_ticks=queued[1],
                         sensor=queued[2],reason=reason)

    def launch(self, task, row):
        kind = task[2]
        if task[:2] not in self.known:
            self.discard_pending_identity(task[:2], "MISSING_BEFORE_LAUNCH")
            return
        identity, err = self.native.identity(row["pid"])
        if not identity or identity["creation_ticks"] != row["creation_ticks"]:
            self.log("IDENTITY_CHANGED_BEFORE_SCAN", pid=row["pid"], sensor=kind, win32_error=err)
            self.discard_pending_identity(task[:2], "CHANGED_BEFORE_LAUNCH"); return
        self.seq += 1
        folder = self.session / "monitoraggio" / "workers" / ("%06d_%d_%s" % (self.seq,row["pid"],"p" if kind == "pe-sieve" else "m"))
        folder.mkdir(parents=True)
        settings = {
            "Gate":str(folder / "go"), "TargetPid":row["pid"], "Targets":self.cfg["targets"],
            "PeSievePath":self.cfg["pe_sieve_path"], "MonetaPath":self.cfg["moneta_path"], "SensorKind":kind,
            "OutputLog":str(folder / "events.jsonl"), "WorkRoot":str(folder / "reports"), "RunId":self.session.name,
            "ResultPath":str(folder / "result.json"), "TimeoutSeconds":self.cfg["scanner_timeout_seconds"],
            "ExpectedProcessStartUTC":row["process_start_utc"],
            "SensorPath":str(self.asset / ("Invoke-MonetaMemorySensor.ps1" if kind == "moneta" else "Invoke-MemoryIntegritySensor.ps1"))}
        write_json(folder / "settings.json", settings)
        output = (folder / "worker-console.txt").open("wb")
        proc = None
        try:
            proc = subprocess.Popen([self.ps,"-NoLogo","-NoProfile","-NonInteractive","-File",
                                     str(self.asset / "worker.ps1"),"-SettingsPath",str(folder / "settings.json")],
                                    stdin=subprocess.DEVNULL,stdout=output,stderr=subprocess.STDOUT,
                                    creationflags=subprocess.CREATE_NO_WINDOW)
            job = self.native.job(proc)
            self.running[task] = {"proc":proc,"job":job,"output":output,"folder":folder,"row":row,
                                  "kind":kind,"started":time.monotonic(),"phase":self.phase}
            worker_identity, _ = self.native.identity(proc.pid)
            if worker_identity:
                self.register_runtime(worker_identity,"WORKER",kind)
            (folder / "go").touch()
            self.coverage[task[:2]]["sensors"][kind]["attempted"] += 1
            self.log("SCAN_STARTED",pid=task[0],creation_ticks=task[1],sensor=kind,worker_pid=proc.pid,
                     phase=self.phase,worker=str(folder.relative_to(self.session)),
                     scheduling_reason=self.scheduling_reason(task),
                     first_seen_utc=row["discovered_utc"],
                     discovery_to_start_ms=round(1000*(time.monotonic()-row["discovered_monotonic"])))
        except Exception:
            if proc is not None:
                if task in self.running:
                    self.finish(task,"WORKER_LAUNCH_ERROR")
                else:
                    proc.kill(); proc.wait(timeout=5)
            output.close()
            raise

    def publish(self, ob, kind, phase):
        if self.baseline_end_utc and ob.get("scan_start_utc"):
            phase="BASELINE" if parse_time(ob["scan_start_utc"]) < parse_time(self.baseline_end_utc) else "OBSERVATION"
        ob.update(session_id=self.session.name,hostname=socket.gethostname(),orchestrator_version=VERSION,
                  observation_phase=phase,memory_detection_class=memory_detection_class(ob),
                  publication_status="PUBLISHED",publication_error=None)
        for attempt in range(5):
            try:
                append_json(self.cfg["telemetry_path"], ob)
                break
            except OSError as exc:
                if attempt == 4:
                    ob["publication_status"], ob["publication_error"] = "WRITE_ERROR", str(exc)
                else:
                    time.sleep(.1)
        append_json(self.telemetry,ob)
        if ob["publication_status"] != "PUBLISHED":
            self.log("TELEMETRY_WRITE_ERROR",pid=ob["pid"],sensor=kind,error=ob["publication_error"])
        return ob["publication_status"]

    def finish(self, task, forced=None):
        w = self.running.pop(task)
        kind = w["kind"]
        self.native.k.CloseHandle(w["job"])
        try:
            w["proc"].wait(timeout=5)
        except subprocess.TimeoutExpired:
            w["proc"].kill(); w["proc"].wait(timeout=5)
        w["output"].close()
        self.close_runtime(w["proc"].pid)
        outcome, publication = forced or "WORKER_ERROR", []
        try:
            if forced:
                raise ValueError(forced)
            if w["proc"].returncode != 0:
                raise ValueError("WORKER_EXIT_CODE_%s" % w["proc"].returncode)
            observations = result_observations(read_json(w["folder"] / "result.json"))
            targets = self.cfg["targets"][:1] if kind == "moneta" else self.cfg["targets"]
            if len(observations) != len(targets):
                raise ValueError("OBSERVATION_COUNT_MISMATCH")
            for ob,target in zip(observations,targets):
                if (not isinstance(ob,dict) or ob.get("pid") != task[0] or ob.get("run_id") != self.session.name
                        or ob.get("sensor") != kind or str(ob.get("target_module","")).casefold() != target["Module"].casefold()
                        or ob.get("target_function") != target["Function"]):
                    raise ValueError("SENSOR_IDENTITY_OR_TARGET_MISMATCH")
                if ob.get("process_start_utc") and parse_time(ob["process_start_utc"]) != parse_time(w["row"]["process_start_utc"]):
                    raise ValueError("SENSOR_PROCESS_CREATION_MISMATCH")
            outcome = "SCAN_COMPLETED" if all(o.get("scan_completed") is True for o in observations) else "SCAN_PARTIAL_OR_ERROR"
            publication = [self.publish(ob,kind,w["phase"]) for ob in observations]
        except (OSError,ValueError,TypeError) as exc:
            self.log("WORKER_EVIDENCE_ERROR",pid=task[0],sensor=kind,error=str(exc))
        if outcome == "SCAN_COMPLETED":
            self.last_completed_display = "%s — %s — PID %s" % (kind,w["row"].get("name","?"),task[0])
        self.log(outcome,pid=task[0],creation_ticks=task[1],sensor=kind,
                 worker=str(w["folder"].relative_to(self.session)),publication=publication)
        coverage = self.coverage[task[:2]]["sensors"][kind]
        coverage["completed" if outcome == "SCAN_COMPLETED" else "errors"] += 1
        if outcome == "SCAN_COMPLETED":
            observed_phase=observations[0].get("observation_phase",w["phase"])
            coverage["completed_by_phase"][observed_phase] += 1
        if task[:2] in self.known:
            row = self.known[task[:2]]
            current = time.monotonic()
            if outcome != "SCAN_COMPLETED":
                interval = self.cfg["retry_seconds"]
            elif current < row["watch_until"]:
                interval = self.cfg["new_process_rescan_seconds"]
            else:
                interval = self.cfg["rescan_seconds"]
            row["due_by_sensor"][kind] = current + interval
            row["priority_by_sensor"][kind] = 2

    def scheduling_reason(self, task):
        row = self.known[task[:2]]
        stats = self.coverage[task[:2]]["sensors"][task[2]]
        if stats["attempted"] <= 1 and task in self.running:
            # launch increments attempted before recording its event.
            attempted_before_launch = stats["attempted"] - 1
        else:
            attempted_before_launch = stats["attempted"]
        if attempted_before_launch == 0:
            return "NEW_PROCESS_FIRST_PASS" if row["discovered_after_initial"] else (
                "SCRIPT_HOST_FIRST_PASS" if row["script_host"] else "INITIAL_FIRST_PASS")
        if stats["errors"] and not stats["completed"]:
            return "RETRY"
        return "EARLY_RECHECK" if time.monotonic() < row["watch_until"] else "PERIODIC_RESCAN"

    def select_task(self, eligible):
        # A previous launch in this tick may have invalidated both queued sensors.
        for identity in {task[:2] for task in eligible if task[:2] not in self.known}:
            self.discard_pending_identity(identity, "STALE_SCHEDULER_ENTRY")
        eligible = [task for task in eligible if task in self.pending and task[:2] in self.known]
        if not eligible:
            return None
        current = time.monotonic()
        def first_pass(task):
            return self.coverage[task[:2]]["sensors"][task[2]]["attempted"] == 0
        def age(task):
            return (self.pending[task]["due"], self.modes.index(task[2]), task[0])
        # Every fourth dispatch makes progress on the oldest unattempted task.
        # This is a dispatch guarantee, not a wall-clock latency guarantee.
        if self.new_streak >= self.cfg["priority_burst"]:
            initial = [task for task in eligible if first_pass(task)]
            self.new_streak = 0
            return min(initial or eligible, key=age)
        def rank(task):
            row = self.known[task[:2]]
            stats = self.coverage[task[:2]]["sensors"][task[2]]
            if first_pass(task):
                lane = 0 if row["discovered_after_initial"] else (1 if row["script_host"] else 2)
            elif stats["errors"] and not stats["completed"]:
                lane = 4
            else:
                lane = 1 if row["script_host"] or current < row["watch_until"] else 3
            other_attempted = any(v["attempted"] > 0 for name,v in self.coverage[task[:2]]["sensors"].items() if name != task[2])
            pair = 0 if first_pass(task) and other_attempted else 1
            # First passes within each lane precede repeat checks.
            return (lane, 0 if first_pass(task) else 1, pair, *age(task))
        self.new_streak += 1
        return min(eligible, key=rank)

    def tick(self, stopping=False):
        current = time.monotonic()
        for task,w in list(self.running.items()):
            if w["proc"].poll() is not None:
                self.finish(task)
            elif current - w["started"] > self.cfg["worker_timeout_seconds"]:
                self.finish(task,"WORKER_TIMEOUT")
        if stopping:
            return
        if current >= self.next_inventory:
            self.refresh(); self.next_inventory = current + self.cfg["inventory_seconds"]
        while self.pending and len(self.running) < self.cfg["max_concurrent_scans"]:
            busy = {task[:2] for task in self.running}
            eligible = [task for task in self.pending if task[:2] not in busy]
            if not eligible:
                break
            task = self.select_task(eligible)
            if task is None:
                break
            self.launch(task,self.pending.pop(task))

    def status(self):
        return {"in_coda":len(self.pending),"in_corso":len(self.running),"fase":self.phase,
                "sensori":{k:dict(v) for k,v in self.sensor_counts.items()},"conteggi":dict(self.counts)}

    def finalize(self, reason):
        requested = now()
        deadline = time.monotonic() + self.cfg["stop_grace_seconds"]
        try:
            while self.running and time.monotonic() < deadline:
                self.tick(stopping=True); time.sleep(.2)
        except KeyboardInterrupt:
            reason = "FORCED_STOP"
        finally:
            for task in list(self.running):
                self.finish(task,"STOP_GRACE_EXCEEDED")
            for task in self.pending:
                self.log("NOT_SCANNED_AT_STOP",pid=task[0],creation_ticks=task[1],sensor=task[2])
        end = now()
        for record in self.runtime.values():
            if not record["end_utc"]:
                record["end_utc"] = end
        write_json(self.session / "monitoraggio" / "processi_sensore.json",list(self.runtime.values()))
        rows = list(self.coverage.values())
        complete_both = sum(all(r["sensors"][s]["completed"] > 0 for s in self.modes) for r in rows)
        observation_both = sum(all(r["sensors"][s]["completed_by_phase"]["OBSERVATION"] > 0 for s in self.modes) for r in rows)
        coverage = {"enabled_sensors":list(self.modes),"processes_observed":len(rows),
                    "processes_completed_by_all_sensors":complete_both,
                    "processes_completed_by_all_during_observation":observation_both,
                    "processes_without_all_completed":len(rows)-complete_both,"processes":rows,
                    "interpretation":"Operational acquisition coverage, not RAT detection or benchmark performance metric"}
        write_json(self.session / "monitoraggio" / "copertura_sensori.json",coverage)
        self.stop_info = {"stop_requested_utc":requested,"end_utc":end,"stop_reason":reason,
                          "baseline_end_utc":self.baseline_end_utc,"counts":dict(self.counts),
                          "sensor_counts":{k:dict(v) for k,v in self.sensor_counts.items()},
                          "pending_at_stop":len(self.pending),"coverage_summary":{k:v for k,v in coverage.items() if k != "processes"}}
        print("Copertura: %d/%d processi completati da tutti i sensori nella sessione; %d durante OBSERVATION. Vedere copertura_sensori.json." % (complete_both,len(rows),observation_both))
        for kind in self.modes:
            if not self.sensor_counts[kind]["SCAN_COMPLETED"]:
                print("ATTENZIONE: nessuna scansione completata da %s; non interpretare come assenza di detection." % kind)
        return self.stop_info

    def run(self):
        import msvcrt
        if not sys.stdin.isatty():
            raise RuntimeError("Usare una console Windows interattiva")
        def read_command():
            while msvcrt.kbhit():
                char = msvcrt.getwch()
                if char == "\x03":
                    raise KeyboardInterrupt
                if char in ("\x00","\xe0"):
                    msvcrt.getwch(); continue
                if char in ("\r","\n"):
                    print(); line,self.command_buffer=self.command_buffer,""; return line.strip()
                if char == "\b":
                    if self.command_buffer:
                        self.command_buffer=self.command_buffer[:-1]; print("\b \b",end="",flush=True)
                elif char.isprintable():
                    self.command_buffer += char; print(char,end="",flush=True)
            return ""
        started = time.monotonic()
        display_settings = presentation_settings(self.session)
        live_console = enable_console_vt()
        next_display = 0.0
        append_json(self.session / "marcatori.jsonl",{"timestamp":now(),"event":"MONITOR_START","phase":self.phase})
        print("Sensori attivi: %s. Comandi: STATO, MARCA testo, STOP (Invio)." % ", ".join(self.modes))
        if self.phase == "BASELINE":
            print("CONTROLLO INIZIALE per %s secondi: tenere il RAT fermo; scanner gia attivi." % self.cfg["baseline_seconds"])
        reason = "STOP"
        try:
            while True:
                if self.phase == "BASELINE" and time.monotonic()-started >= self.cfg["baseline_seconds"]:
                    self.phase="OBSERVATION"; self.baseline_end_utc=now()
                    append_json(self.session / "marcatori.jsonl",{"timestamp":self.baseline_end_utc,"event":"BASELINE_END"})
                    print("CONTROLLO INIZIALE TERMINATO. Il team puo iniziare il RAT; usare MARCA Inizio RAT.")
                cmd=read_command()
                if cmd.upper() == "STOP":
                    break
                if cmd.upper() == "STATO":
                    print(monitor_panel(self,time.monotonic()-started))
                    next_display = 0.0
                elif cmd.upper().startswith("MARCA "):
                    self.last_marker_display = cmd[6:]
                    next_display = 0.0
                    append_json(self.session / "marcatori.jsonl",{"timestamp":now(),"event":"OPERATOR_NOTE","note":cmd[6:]})
                elif cmd:
                    print("Usare STATO, MARCA testo oppure STOP.")
                self.tick()
                # Pause redraw while the operator types; preserve the existing input reader.
                if live_console and not self.command_buffer and time.monotonic() >= next_display:
                    print("\x1b[2J\x1b[H"+monitor_panel(self,time.monotonic()-started),end="",flush=True)
                    next_display = time.monotonic()+display_settings["refresh_seconds"]
                if self.cfg["max_session_minutes"] and time.monotonic()-started >= self.cfg["max_session_minutes"]*60:
                    reason="MAX_DURATION"; break
                time.sleep(.2)
        except KeyboardInterrupt:
            reason="INTERRUPTED"
        finally:
            self.finalize(reason)
        return self.stop_info


def monitor_session(cfg):
    native=Windows()
    if ctypes.sizeof(ctypes.c_void_p) != 8:
        raise RuntimeError("Usare Python e scanner a 64 bit")
    if not ctypes.windll.shell32.IsUserAnAdmin():
        raise RuntimeError("Aprire la console con Esegui come amministratore (UAC standard)")
    binaries={kind:Path(cfg["pe_sieve_path"] if kind=="pe-sieve" else cfg["moneta_path"]) for kind in active_sensors(cfg)}
    for kind,path in binaries.items():
        if not path.is_file():
            raise FileNotFoundError("Scanner %s non trovato: %s" % (kind,path))
    telemetry=Path(cfg["telemetry_path"]); telemetry.parent.mkdir(parents=True,exist_ok=True)
    with telemetry.open("a",encoding="utf-8"):
        pass
    prefix=re.sub(r"[^A-Za-z0-9_.-]","_",cfg["session_prefix"])
    session=Path(cfg["output_root"])/(prefix+"_"+datetime.now(UTC).strftime("%Y%m%dT%H%M%SZ")+"_"+uuid.uuid4().hex[:6])
    session.mkdir(parents=True)
    meta={"session_id":session.name,"version":VERSION,"hostname":socket.gethostname(),"start_utc":now(),
          "end_utc":None,"state":"PREPARING","sensor_mode":cfg["sensor_mode"],"scanners":{},
          "wazuh_delivery":"NOT_VERIFIED","scope":"single Windows-HR endpoint; RAT operated independently"}
    for kind,path in binaries.items():
        meta["scanners"][kind]={"binary_sha256":hashlib.sha256(path.read_bytes()).hexdigest(),"sensor_sha256":sensor_sha256_for_mode(kind)}
    snapshot=dict(cfg); snapshot["export"]={k:v for k,v in cfg["export"].items() if k not in ("username","password_environment")}
    write_json(session/"configurazione_utilizzata.json",snapshot); write_json(session/"session.json",meta)
    mon=None
    try:
        mon=Monitor(cfg,session,native); mon.preflight()
        meta["prepared_utc"],meta["start_utc"],meta["state"]=meta["start_utc"],now(),"MONITORING"
        write_json(session/"session.json",meta)
        print("Sessione:",session)
        print("Ricezione Wazuh da confermare nel collaudo. Nessun PID RAT viene usato per scegliere i target.")
        meta.update(mon.run()); meta["state"]="STOPPED"
    except (Exception,KeyboardInterrupt) as exc:
        meta.update(state="FAILED",end_utc=now(),error=type(exc).__name__+": "+str(exc))
        if mon and hasattr(mon,"stop_info"):
            meta.update(mon.stop_info)
        raise
    finally:
        write_json(session/"session.json",meta)
    return session,meta



class IndexerClient:
    def __init__(self, cfg):
        self.cfg = cfg
        url = urllib.parse.urlsplit(cfg["indexer_url"])
        if url.scheme != "https" or not url.netloc or url.username or url.password or url.query or url.fragment:
            raise ValueError("indexer_url deve essere HTTPS senza credenziali, query o fragment")
        if "INSERIRE" in url.netloc:
            raise ValueError("Configurare export.indexer_url")
        self.url = cfg["indexer_url"].rstrip("/")
        context = ssl.create_default_context(cafile=cfg["ca_file"] or None)
        self.opener = urllib.request.build_opener(urllib.request.ProxyHandler({}),
                                                  urllib.request.HTTPSHandler(context=context), NoRedirect())
        user = cfg["username"] or input("Utente indexer (sola lettura): ").strip()
        password = os.environ.get(cfg["password_environment"]) or getpass.getpass("Password indexer: ")
        if not user or ":" in user or not password:
            raise ValueError("Credenziali indexer mancanti/non valide")
        self.auth = "Basic " + base64.b64encode((user + ":" + password).encode()).decode()

    def request(self, method, path, body):
        req = urllib.request.Request(self.url + path, data=json.dumps(body).encode(), method=method,
                                     headers={"Authorization": self.auth, "Content-Type": "application/json"})
        try:
            with self.opener.open(req, timeout=self.cfg["request_timeout_seconds"]) as response:
                return json.load(response)
        except urllib.error.HTTPError as exc:
            raise RuntimeError("Indexer HTTP %s: verificare indirizzo e permessi search/scroll/clear-scroll" % exc.code) from None
        except urllib.error.URLError:
            raise RuntimeError("Indexer non raggiungibile o certificato non verificato: verificare rete e ca_file") from None


class NoRedirect(urllib.request.HTTPRedirectHandler):
    def redirect_request(self, req, fp, code, msg, headers, newurl):
        return None


def build_query(agent_id, start, end, page_size):
    if not re.fullmatch(r"\d{3,}", str(agent_id)) or str(agent_id) == "000":
        raise ValueError("Configurare l'ID numerico esatto dell'agente Windows-HR, es. 007; non 000")
    if start >= end:
        raise ValueError("Inizio deve precedere fine")
    if not isinstance(page_size, int) or isinstance(page_size, bool) or not 1 <= page_size <= 10000:
        raise ValueError("page_size deve essere tra 1 e 10000")
    return {"size": page_size, "track_total_hits": True, "sort": ["_doc"],
            "query": {"bool": {"filter": [{"term": {"agent.id": str(agent_id)}},
                                               {"range": {"timestamp": {"gte": stamp(start), "lte": stamp(end)}}}]}}}


def check_page(page):
    if page.get("timed_out") or page.get("_shards", {}).get("failed", 0):
        raise ValueError("Ricerca incompleta: timeout o shard falliti")
    if not isinstance(page.get("hits", {}).get("hits"), list):
        raise ValueError("Risposta indexer non valida")


def export_alerts_indexer(cfg, session, start, end, client=None):
    ec = cfg["export"]
    for key in ("before_seconds", "after_seconds", "ingestion_wait_seconds"):
        if not isinstance(ec[key], (int, float)) or ec[key] < 0:
            raise ValueError("Valore non negativo richiesto: export." + key)
    query_start = start - timedelta(seconds=ec["before_seconds"])
    query_end = end + timedelta(seconds=ec["after_seconds"])
    query = build_query(ec["agent_id"], query_start, query_end, ec["page_size"])
    pattern = ec["index_pattern"]
    if not re.fullmatch(r"wazuh-alerts-[A-Za-z0-9*_.-]+|wazuh-alerts-\*", pattern):
        raise ValueError("index_pattern deve selezionare esclusivamente indici wazuh-alerts-...")
    folder = session / "esportazioni" / ("export_" + datetime.now(UTC).strftime("%Y%m%dT%H%M%SZ") + "_" + uuid.uuid4().hex[:6])
    folder.mkdir(parents=True)
    write_json(folder / "richiesta.json", {"requested_start_utc": stamp(start), "requested_end_utc": stamp(end),
                "query_start_utc": stamp(query_start), "query_end_utc": stamp(query_end),
                "index_pattern": pattern, "query": query, "agent_id": ec["agent_id"],
                "time_basis": "Wazuh indexed alert timestamp; not necessarily endpoint activity time",
                "created_utc": now()})
    summary = {"status": "IN_PROGRESS", "exported": 0, "expected": None,
               "started_utc": now(), "agent_id": ec["agent_id"],
               "delivery_completeness": "NOT_PROVEN_BY_EXPORT", "rules": {}}
    write_json(folder / "riepilogo.json", summary)
    cursor = None
    partial = folder / "alert.partial.jsonl"
    try:
        # Wait relative to the query END, so an enlarged after-margin is actually respected.
        remaining = max(0, (query_end + timedelta(seconds=ec["ingestion_wait_seconds"]) - datetime.now(UTC)).total_seconds())
        if remaining:
            print("Attesa raccolta/indicizzazione: %.0f secondi (Ctrl+C annulla solo esportazione)." % remaining)
            while remaining > 0:
                time.sleep(min(1, remaining))
                remaining = max(0, (query_end + timedelta(seconds=ec["ingestion_wait_seconds"]) - datetime.now(UTC)).total_seconds())
        client = client or IndexerClient(ec)
        page = client.request("POST", "/" + urllib.parse.quote(pattern, safe="*_.-") + "/_search?scroll=2m&allow_partial_search_results=false", query)
        cursor = page.get("_scroll_id")
        check_page(page)
        total = page["hits"].get("total")
        if isinstance(total, dict):
            if total.get("relation") != "eq":
                raise ValueError("Conteggio totale non esatto")
            total = total.get("value")
        if not isinstance(total, int) or total < 0:
            raise ValueError("Conteggio totale assente")
        summary["expected"] = total
        seen, rules = set(), collections.Counter()
        with partial.open("w", encoding="utf-8", newline="\n") as out:
            while True:
                check_page(page)
                hits = page["hits"]["hits"]
                if not hits:
                    break
                for hit in hits:
                    uid = (hit.get("_index"), hit.get("_id"))
                    if not all(uid) or uid in seen:
                        raise ValueError("Documento senza identita o duplicato nella paginazione")
                    seen.add(uid)
                    source = hit.get("_source", {})
                    if str(source.get("agent", {}).get("id", "")) != str(ec["agent_id"]):
                        raise ValueError("Risposta con agente differente da quello richiesto")
                    alert_time = parse_time(source.get("timestamp"))
                    if not query_start <= alert_time <= query_end:
                        raise ValueError("Risposta con timestamp fuori finestra")
                    out.write(json.dumps(hit, ensure_ascii=False, separators=(",", ":")) + "\n")
                    summary["exported"] += 1
                    rules[str(source.get("rule", {}).get("id", "unknown"))] += 1
                out.flush()
                if not cursor:
                    if summary["exported"] == total:
                        break
                    raise ValueError("Scroll ID mancante con risultati ancora da leggere")
                page = client.request("POST", "/_search/scroll", {"scroll": "2m", "scroll_id": cursor})
                cursor = page.get("_scroll_id", cursor)
            if summary["exported"] != total:
                raise ValueError("Conteggio esportato diverso dal totale della ricerca")
        partial.rename(folder / "alert.jsonl")
        summary.update(status="COMPLETE", rules=dict(rules))
    except (Exception, KeyboardInterrupt) as exc:
        summary.update(status="FAILED_OR_PARTIAL", error=type(exc).__name__ + ": " + str(exc))
        raise
    finally:
        if cursor and client:
            try:
                client.request("DELETE", "/_search/scroll", {"scroll_id": [cursor]})
            except Exception:
                summary["scroll_cleanup_warning"] = "Chiusura scroll non confermata; scadenza automatica lato server"
        summary["finished_utc"] = now()
        write_json(folder / "riepilogo.json", summary)
    print("Esportazione completata: %d alert in %s" % (summary["exported"], folder))
    return folder


def ask_window(meta, args):
    start, end = args.start or meta.get("start_utc"), args.end or meta.get("end_utc")
    if not args.yes:
        print("Inserire ISO 8601 con fuso, ad esempio 2026-10-27T09:00:00+01:00; Invio mantiene il valore.")
        start = input("Inizio [%s]: " % (start or "obbligatorio" )).strip() or start
        end = input("Fine   [%s]: " % (end or "obbligatorio" )).strip() or end
    if not start or not end:
        raise ValueError("Specificare --start e --end o una sessione terminata")
    return parse_time(start), parse_time(end)


MANAGER_READER_B64 = ""


def ssh_command(ec, params):
    host = ec["manager_host"]
    if not re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9.:-]*", host) or "INSERIRE" in host:
        raise ValueError("Configurare export.manager_host con IP/nome della macchina Ubuntu")
    user = ec["ssh_user"]
    if not re.fullmatch(r"[A-Za-z_][A-Za-z0-9_.-]*", user):
        raise ValueError("Configurare export.ssh_user con l'utente Ubuntu autorizzato a leggere gli alert")
    port = ec["ssh_port"]
    if not isinstance(port, int) or isinstance(port, bool) or not 1 <= port <= 65535:
        raise ValueError("ssh_port non valida")
    executable = shutil.which(ec["ssh_executable"])
    if not executable:
        raise FileNotFoundError("Client OpenSSH non trovato. Configurare ssh_executable o usare export dalla macchina di management")
    command = [executable, "-T", "-o", "StrictHostKeyChecking=ask", "-o", "ConnectTimeout=15",
               "-o", "ServerAliveInterval=15", "-o", "ServerAliveCountMax=3", "-p", str(port), "-l", user]
    if ec["ssh_identity_file"]:
        if not Path(ec["ssh_identity_file"]).is_file():
            raise FileNotFoundError("Chiave SSH configurata non trovata")
        command += ["-i", ec["ssh_identity_file"]]
    # Base64 parameters contain no shell metacharacters; code and executable still quoted.
    payload = base64.b64encode(json.dumps(params).encode()).decode()
    bootstrap = "import base64;exec(compile(base64.b64decode(" + repr(MANAGER_READER_B64) + "),'<hr-reader>','exec'))"
    remote = "python3 -c " + shlex.quote(bootstrap) + " " + shlex.quote(payload)
    return command + [host, remote]


def decode_manager_stream(stream_path, folder, agent_id, start, end):
    count, rules, remote_summary = 0, collections.Counter(), None
    begun = False
    issue_count = 0
    partial = folder / "alert.partial.jsonl"
    with Path(stream_path).open(encoding="utf-8") as source, partial.open("w", encoding="utf-8", newline="\n") as out:
        for line in source:
            row = json.loads(line)
            kind = row.get("kind")
            if remote_summary is not None:
                raise ValueError("Dati dopo il riepilogo remoto")
            if kind == "begin":
                if begun or row.get("agent_id") != agent_id or parse_time(row.get("start")) != start or parse_time(row.get("end")) != end:
                    raise ValueError("Intestazione remota non corrisponde alla richiesta")
                begun = True
            elif kind == "alert":
                if not begun:
                    raise ValueError("Intestazione remota assente")
                alert = row["alert"]
                if str(alert.get("agent", {}).get("id", "")) != agent_id or not start <= parse_time(alert.get("timestamp")) <= end:
                    raise ValueError("Alert remoto fuori finestra o agente errato")
                out.write(json.dumps(alert, ensure_ascii=False, separators=(",", ":")) + "\n")
                append_json(folder / "provenienza.jsonl", {"alert_number":count + 1, "source_file":row.get("source_file"), "line":row.get("line")})
                count += 1
                rules[str(alert.get("rule", {}).get("id", "unknown"))] += 1
            elif kind == "issue":
                if not begun:
                    raise ValueError("Intestazione remota assente prima del problema di lettura")
                issue_count += 1
                append_json(folder / "problemi_lettura.jsonl", row)
            elif kind == "summary":
                remote_summary = row
            elif kind == "error":
                raise RuntimeError("Lettura Ubuntu: " + row.get("message", "errore sconosciuto"))
            else:
                raise ValueError("Record remoto sconosciuto")
    if not begun or not remote_summary:
        raise ValueError("Trasferimento remoto interrotto: manca il riepilogo")
    if remote_summary.get("status") not in ("COMPLETE", "PARTIAL") or remote_summary.get("exported") != count:
        raise ValueError("Stato remoto o conteggi non coerenti")
    if remote_summary.get("malformed_lines", 0) != issue_count:
        raise ValueError("Conteggio problemi di lettura non coerente")
    if remote_summary.get("status") == "COMPLETE" and issue_count:
        raise ValueError("Completezza remota incoerente")
    if remote_summary.get("status") == "PARTIAL" and not issue_count:
        raise ValueError("Raccolta parziale senza problemi documentati")
    partial.rename(folder / "alert.jsonl")
    return {"exported":count, "rules":dict(rules), "remote":remote_summary}


def export_alerts_ssh(cfg, session, start, end):
    ec = cfg["export"]
    build_query(ec["agent_id"], start, end, ec["page_size"])  # Shared strict identity/window validation.
    for key in ("before_seconds", "after_seconds", "ingestion_wait_seconds", "ssh_timeout_seconds"):
        if not isinstance(ec[key], (int, float)) or isinstance(ec[key], bool) or not math.isfinite(ec[key]) or ec[key] < 0:
            raise ValueError("Valore non negativo richiesto: export." + key)
    query_start = start - timedelta(seconds=ec["before_seconds"])
    query_end = end + timedelta(seconds=ec["after_seconds"])
    params = {"directory":ec["manager_alerts_directory"], "start":stamp(query_start),
              "end":stamp(query_end), "agent_id":str(ec["agent_id"])}
    command = ssh_command(ec, params)
    folder = session / "esportazioni" / ("ssh_" + datetime.now(UTC).strftime("%Y%m%dT%H%M%SZ") + "_" + uuid.uuid4().hex[:6])
    folder.mkdir(parents=True)
    write_json(folder / "richiesta.json", {"transport":"ssh", "manager_host":ec["manager_host"],
        "requested_start_utc":stamp(start), "requested_end_utc":stamp(end), **params,
        "time_basis":"Wazuh manager alert timestamp; not necessarily endpoint activity time"})
    summary = {"status":"IN_PROGRESS", "started_utc":now(), "transport":"ssh",
               "delivery_completeness":"NOT_PROVEN_BY_EXPORT", "agent_id":str(ec["agent_id"])}
    write_json(folder / "riepilogo.json", summary)
    try:
        deadline = query_end + timedelta(seconds=ec["ingestion_wait_seconds"])
        remaining = max(0, (deadline - datetime.now(UTC)).total_seconds())
        if remaining:
            print("Attesa degli ultimi alert sul manager: %.0f secondi." % remaining)
        while remaining > 0:
            time.sleep(min(1, remaining))
            remaining = max(0, (deadline - datetime.now(UTC)).total_seconds())
        print("Connessione SSH a Ubuntu. Confermare l'impronta del server solo dopo verifica; password richiesta da OpenSSH se necessaria.")
        stream_path = folder / "manager_stream.jsonl"
        with stream_path.open("wb") as out:
            proc = subprocess.Popen(command, stdout=out)  # Keep console available for SSH authentication.
            try:
                code = proc.wait(timeout=ec["ssh_timeout_seconds"])
            except (Exception, KeyboardInterrupt):
                proc.kill(); proc.wait(timeout=5)
                raise
        if code != 0:
            # Parse error records for a useful reason, but never finalize an unsuccessful transfer.
            messages = []
            try:
                for line in stream_path.read_text(encoding="utf-8").splitlines():
                    row = json.loads(line)
                    if row.get("kind") == "error": messages.append(row.get("message", ""))
            except (OSError, ValueError):
                pass
            raise RuntimeError("SSH/lettura manager fallita (codice %s). %s Verificare accesso SSH, Python3 e permessi di lettura degli alert." % (code, "; ".join(messages)))
        summary.update(decode_manager_stream(stream_path, folder, str(ec["agent_id"]), query_start, query_end))
        summary["status"] = summary["remote"]["status"]
    except (Exception, KeyboardInterrupt) as exc:
        summary.update(status="FAILED_OR_PARTIAL", error=type(exc).__name__ + ": " + str(exc))
        raise
    finally:
        summary["finished_utc"] = now()
        write_json(folder / "riepilogo.json", summary)
    print("Esportazione SSH %s: %d alert in %s" % (summary["status"], summary["exported"], folder))
    if summary["status"] == "PARTIAL":
        print("ATTENZIONE: raccolta parziale. Alcuni record non leggibili; vedere problemi_lettura.jsonl. Gli alert validi sono conservati.")
    return folder


def export_alerts(cfg, session, start, end, client=None):
    if cfg["export"].get("transport", "ssh") == "ssh" and client is None:
        folder = export_alerts_ssh(cfg, session, start, end)
    else:
        folder = export_alerts_indexer(cfg, session, start, end, client)
    try:
        annotate_export(folder, session)
    except Exception as exc:
        write_json(folder / "classificazione_errore.json", {"error":str(exc),"original_export_intact":True})
        print("Alert esportati; annotazione non completata. Vedere classificazione_errore.json")
    try:
        present_export(folder, session)
    except Exception as exc:
        write_json(folder / "presentazione_errore.json", {"error":str(exc),"original_export_intact":True})
        print("ATTENZIONE: presentazione non completata; alert originali conservati. Vedere presentazione_errore.json")
    return folder


def nested_value(data, *path):
    for name in path:
        if not isinstance(data,dict):
            return None
        key=next((k for k in data if str(k).casefold()==name.casefold()),None)
        if key is None:
            return None
        data=data[key]
    return data


def annotate_alert(alert, runtime, meta):
    source=alert.get("_source",alert)
    memory=nested_value(source,"data")
    if not isinstance(memory,dict):
        memory={}
    if memory.get("source")=="memory_integrity":
        return {"classification":"MEMORY_SENSOR_OBSERVATION","meaning":"Signal about the scanned target; not automatically monitoring noise",
                "sensor":memory.get("sensor"),"session_id":memory.get("session_id"),
                "observation_phase":memory.get("observation_phase"),"memory_detection_class":memory.get("memory_detection_class")}
    provider=nested_value(source,"data","win","system","providerName") or ""
    if "powershell" in str(provider).casefold():
        pid=nested_value(source,"data","win","system","processID")
    elif "sysmon" in str(provider).casefold():
        pid=nested_value(source,"data","win","eventdata","processId")
    else:
        pid=None
    try:
        pid=int(str(pid),16 if str(pid).lower().startswith("0x") else 10)
    except (ValueError,TypeError):
        return {"classification":"UNATTRIBUTED","meaning":"No reliable producing PID; manual comparison with RAT action log required"}
    source_time=nested_value(source,"data","win","system","systemTime")
    fallback=source.get("timestamp")
    try:
        when=parse_time(source_time or fallback)
    except (ValueError,TypeError):
        return {"classification":"UNATTRIBUTED","meaning":"Missing or invalid timestamp"}
    matching=[]
    for process in runtime:
        try:
            if process["pid"]==pid and parse_time(process["start_utc"])<=when<=parse_time(process["end_utc"] or meta["end_utc"]):
                matching.append(process)
        except (ValueError,TypeError,KeyError):
            continue
    if len(matching)==1:
        return {"classification":"SENSOR_RUNTIME_PROCESS" if source_time else "POSSIBLY_SENSOR_RUNTIME_PROCESS",
                "pid":pid,"role":matching[0]["role"],"sensor":matching[0].get("sensor"),
                "timestamp_basis":"endpoint" if source_time else "manager",
                "meaning":"Producing process belongs to monitoring; preserve alert and review, never auto-delete"}
    return {"classification":"UNATTRIBUTED","pid":pid,"meaning":"Not attributed to monitoring; this is not proof of RAT activity"}


def annotate_export(folder,session):
    meta=read_json(session/"session.json")
    runtime_path=session/"monitoraggio"/"processi_sensore.json"
    runtime=read_json(runtime_path) if runtime_path.exists() else []
    counts=collections.Counter()
    with (folder/"alert.jsonl").open(encoding="utf-8") as src, (folder/"classificazione_alert.jsonl").open("w",encoding="utf-8",newline="\n") as out:
        for number,line in enumerate(src,1):
            alert=json.loads(line)
            annotation=annotate_alert(alert,runtime,meta)
            counts[annotation["classification"]]+=1
            source=alert.get("_source",alert)
            out.write(json.dumps({"alert_number":number,"rule_id":nested_value(source,"rule","id"),
                                  "timestamp":source.get("timestamp"),**annotation},ensure_ascii=False)+"\n")
    write_json(folder/"riepilogo_classificazione.json",{"counts":dict(counts),"automatic_rat_verdict":False,
        "original_alerts_modified":False,"runtime_inventory_available":runtime_path.exists(),
        "interpretation":"Attribution aid only. Keep all alerts and compare actual RAT actions and baseline."})



# Presentation only: no scanner, scheduler, export query or rule changes.
PRESENTATION_DEFAULT = {
    "minimum_other_level": 10,
    "include_rule_ids": [str(n) for n in list(range(100201,100211)) +
        [100105,100230,100220,100221,100240,100301,100302] +
        list(range(100311,100318)) + [100331,100332,100333,100410,100411,
        100412,100420,100421,100510,100511]],
    "exclude_rule_ids": [],
    "exclude_location_only_labels": ["executable dropper in public folder",
        "executable in user folder", "executable in public folder"],
    "exclude_confirmed_monitoring_discovery": True,
    "color": True,
    "refresh_seconds": 5
}


def console_text(value):
    # Untrusted event strings must not inject terminal escapes/control sequences.
    return "".join(c if c >= " " and c != "\x7f" and not ("\x80" <= c <= "\x9f") else " "
                   for c in str(value))


def presentation_settings(session):
    path = Path(__file__).with_name("presentazione_alert.json")
    settings = dict(PRESENTATION_DEFAULT)
    if path.exists():
        custom = read_json(path)
        if not isinstance(custom, dict) or set(custom)-set(settings):
            raise ValueError("Configurazione presentazione non valida")
        settings.update(custom)
    if type(settings["minimum_other_level"]) is not int or not 0 <= settings["minimum_other_level"] <= 16:
        raise ValueError("minimum_other_level deve essere un intero 0..16")
    for name in ("include_rule_ids", "exclude_rule_ids", "exclude_location_only_labels"):
        if not isinstance(settings[name], list) or any(not isinstance(x,str) for x in settings[name]):
            raise ValueError("Lista di stringhe richiesta: " + name)
    if type(settings["refresh_seconds"]) is not int or settings["refresh_seconds"] < 1:
        raise ValueError("refresh_seconds deve essere un intero positivo")
    for name in ("color", "exclude_confirmed_monitoring_discovery"):
        if type(settings[name]) is not bool:
            raise ValueError("Booleano richiesto: " + name)
    return settings


def enable_console_vt():
    if not sys.stdout.isatty():
        return False
    if os.name != "nt":
        return True
    mode = wt.DWORD()
    kernel = ctypes.windll.kernel32
    kernel.GetStdHandle.argtypes = [wt.DWORD]
    kernel.GetStdHandle.restype = wt.HANDLE
    kernel.GetConsoleMode.argtypes = [wt.HANDLE, ctypes.POINTER(wt.DWORD)]
    kernel.GetConsoleMode.restype = wt.BOOL
    kernel.SetConsoleMode.argtypes = [wt.HANDLE, wt.DWORD]
    kernel.SetConsoleMode.restype = wt.BOOL
    handle = kernel.GetStdHandle(-11)
    return bool(kernel.GetConsoleMode(handle, ctypes.byref(mode)) and
                kernel.SetConsoleMode(handle, mode.value | 4))


def alert_field(source, *paths):
    for path in paths:
        value = nested_value(source, *path.split("."))
        if value is not None and value != "":
            return value
    return None


def presentation_record(alert, number, settings, runtime, meta):
    source = alert.get("_source", alert)
    rule = str(alert_field(source,"rule.id") or "")
    try:
        level = int(alert_field(source,"rule.level") or 0)
    except (ValueError,TypeError):
        level = 0
    description = str(alert_field(source,"rule.description") or "Descrizione non disponibile")
    label = str(alert_field(source,"data.win.eventdata.ruleName") or "")
    annotation = annotate_alert(alert,runtime,meta)
    discovery = rule in {"100105", "100230", *map(str,range(100201,100211)),
        *map(str,range(100311,100318)), "100331","100332","100333"}
    # Match individual source labels, not command lines/paths or arbitrary substrings.
    # Do not suppress a high-level aggregate merely because one of its labels is generic.
    label_parts = [x.strip().casefold() for x in re.split(r"[,;]", label)]
    excluded_labels = {x.casefold() for x in settings["exclude_location_only_labels"]}
    location_only = (description.strip().casefold() in excluded_labels or
        (rule == "100106" and any(x in excluded_labels for x in label_parts)))
    if rule in settings["exclude_rule_ids"]:
        selected,reason = False,"EXCLUDED_RULE_ID"
    elif location_only:
        selected,reason = False,"LOCATION_ONLY_SIGNAL"
    elif (settings["exclude_confirmed_monitoring_discovery"] and discovery and
          annotation["classification"] == "SENSOR_RUNTIME_PROCESS"):
        selected,reason = False,"CONFIRMED_MONITORING_DISCOVERY"
    elif rule in settings["include_rule_ids"]:
        selected,reason = True,"RELEVANT_RULE"
    elif level >= settings["minimum_other_level"]:
        selected,reason = True,"OTHER_HIGH_LEVEL_ALERT"
    else:
        selected,reason = False,"BELOW_PRESENTATION_THRESHOLD"
    data = source.get("data",{})
    if not isinstance(data,dict): data={}
    memory = data.get("source") == "memory_integrity"
    # Native provider processID may identify a provider, not the target process;
    # use eventdata.processId for Sysmon and label PowerShell's provider PID explicitly.
    details = {}
    fields = {
        "Processo": ("data.image","data.win.eventdata.image","data.win.eventdata.newProcessName"),
        "PID": ("data.pid","data.win.eventdata.processId"),
        "PID provider": ("data.win.system.processID",),
        "Creazione processo": ("data.process_start_utc",),
        "ProcessGuid": ("data.win.eventdata.processGuid",),
        "Modulo": ("data.target_module",), "Funzione": ("data.target_function",),
        "Sensore": ("data.sensor",), "Comando": ("data.win.eventdata.commandLine",),
        "Processo padre": ("data.win.eventdata.parentImage",),
        "Comando PowerShell": ("data.win.eventdata.payload", "data.win.eventdata.scriptBlockText"),
        "Event ID": ("data.win.system.eventID",), "Canale": ("data.win.system.channel",),
        "Stato sensore": ("data.status",), "Classe memoria": ("data.memory_detection_class",),
        "IOC osservati": ("data.ioc_count",), "Fase osservazione": ("data.observation_phase",),
        "Etichetta sorgente": ("data.win.eventdata.ruleName",)
    }
    for name,paths in fields.items():
        value = alert_field(source,*paths)
        if value is not None: details[name]=value
    if "PID" in details: details.pop("PID provider",None)
    timestamp = source.get("timestamp")
    try: normalized_time=stamp(parse_time(timestamp))
    except (ValueError,TypeError): normalized_time=None
    identity = alert_field(source,"data.process_start_utc","data.win.eventdata.processGuid")
    pid = details.get("PID",details.get("PID provider"))
    # Without a creation identity preserve separate alerts, avoiding PID reuse conflation.
    identity_key = str(identity) if identity is not None else "alert:"+str(number)
    key = [str(alert_field(source,"agent.id") or ""),rule,level,pid,identity_key,
        details.get("Processo"),details.get("Modulo"),details.get("Funzione"),
        details.get("Sensore"),details.get("Comando"), details.get("Comando PowerShell"),
        details.get("Etichetta sorgente"),details.get("Canale"),details.get("Event ID"),
        details.get("Stato sensore"),description,details]
    titles={"100412":"MODIFICA DELLA FUNZIONE AMSI", "100411":"MODIFICA DEL MODULO AMSI",
        "100421":"MODIFICA DELLA FUNZIONE ETW", "100420":"MODIFICA DEL MODULO TARGET ETW",
        "100511":"OSSERVAZIONE DI ANOMALIE DELLA MEMORIA — MONETA"}
    return {"alert_number":number,"selected":selected,"reason":reason,"rule_id":rule,
        "level":level,"timestamp":timestamp,"normalized_time":normalized_time,
        "host":alert_field(source,"agent.name") or alert_field(source,"data.hostname"),
        "agent_id":alert_field(source,"agent.id"),"title":titles.get(rule,description),
        "description":description,"details":details,"annotation":annotation,
        "group_key":json.dumps(key,ensure_ascii=False,sort_keys=True),
        "memory_observation":memory}


def build_alert_presentation(alerts, settings, runtime, meta):
    decisions=[];groups={}
    for number,alert in enumerate(alerts,1):
        record=presentation_record(alert,number,settings,runtime,meta)
        decisions.append(record)
        if not record["selected"]: continue
        key=record["group_key"]
        if key not in groups:
            groups[key]={"representative":record,"alert_numbers":[],"times":[]}
        groups[key]["alert_numbers"].append(number)
        if record["normalized_time"]:groups[key]["times"].append(record["normalized_time"])
    rows=list(groups.values())
    for group in rows:
        group["count"]=len(group["alert_numbers"])
        group["first"]=min(group["times"],key=parse_time) if group["times"] else None
        group["last"]=max(group["times"],key=parse_time) if group["times"] else None
        del group["times"]
    rows.sort(key=lambda g:(parse_time(g["first"]).timestamp() if g["first"] else float('inf'),
                           g["alert_numbers"][0]))
    selected=sum(r["selected"] for r in decisions)
    return decisions,rows,{"total":len(decisions),"selected":selected,"groups":len(rows),
        "not_displayed":len(decisions)-selected,
        "decision_counts":dict(collections.Counter(r["reason"] for r in decisions)),
        "automatic_rat_verdict":False,"original_alerts_modified":False}


def render_alert_presentation(groups,summary,request):
    lines=[("ALERT WAZUH RACCOLTI NELLA FINESTRA DELLA SIMULAZIONE",""),
        ("Orari: timestamp degli alert Wazuh, convertiti in UTC.",""),
        ("Finestra richiesta: %s -> %s" % (request.get("requested_start_utc",request.get("start_utc","vedere richiesta.json")),
                                         request.get("requested_end_utc",request.get("end_utc","vedere richiesta.json"))),""),
        ("Le segnalazioni non costituiscono automaticamente attribuzione al RAT.",""), ("","")]
    is_partial = summary.get("collection_status") == "PARTIAL"
    if is_partial:
        lines.insert(1,("ATTENZIONE: RACCOLTA PARZIALE — %s record non leggibili nei file esaminati. La loro appartenenza alla finestra non e verificabile." % summary.get("unreadable_records",0),"yellow"))
    for group in groups:
        r=group["representative"]
        t=group["first"] or "orario non disponibile"
        lines.extend([(f"[{t}] {r['title']}","red"),
            (f"Regola Wazuh: {r['rule_id']} | Livello: {r['level']}","red"),
            (f"Host: {r['host'] or 'non disponibile'} | Agente: {r['agent_id'] or 'non disponibile'}",""),("","")])
        for key,value in r["details"].items():lines.append((f"{key}: {value}",""))
        lines.extend([("", ""),("Descrizione:",""),(r["description"],""),
            ("Attribuzione: "+r["annotation"]["classification"],"")])
        if r["memory_observation"]:
            lines.append(("Osservazione di memoria: non prova da sola l'esecuzione di Ekko o l'origine della modifica.",""))
        if group["count"]>1:
            lines.extend([(f"Stessa segnalazione osservata {group['count']} volte",""),
                (f"Prima osservazione: {group['first']}",""),(f"Ultima osservazione: {group['last']}","")])
        lines.append(("-"*72,""))
    if not groups:lines.append(("Nessun alert corrisponde ai criteri della presentazione; consultare anche la copertura dei sensori.","yellow"))
    lines.extend([("", ""),("RACCOLTA PARZIALE — ALERT LEGGIBILI RECUPERATI" if is_partial else "RACCOLTA COMPLETATA","yellow" if is_partial else ""),
        (f"Alert leggibili nella finestra:         {summary['total']}",""),
        (f"Alert selezionati per la presentazione: {summary['selected']}",""),
        (f"Gruppi di segnalazioni mostrati:         {summary['groups']}",""),
        (f"Altri alert conservati nei risultati:   {summary['not_displayed']}",""),
        ("Raccolta completata non significa copertura completa della telemetria.","")])
    return [(console_text(text),color) for text,color in lines]


def present_export(folder,session):
    summary=read_json(folder/"riepilogo.json")
    if summary.get("status") not in ("COMPLETE", "PARTIAL"):
        raise ValueError("Raccolta fallita: consultare riepilogo.json; nessun esito negativo deducibile")
    settings=presentation_settings(session)
    meta=read_json(session/"session.json")
    path=session/"monitoraggio"/"processi_sensore.json"
    runtime=read_json(path) if path.exists() else []
    alerts=[]
    with (folder/"alert.jsonl").open(encoding="utf-8-sig") as stream:
        for line in stream:
            if line.strip():alerts.append(json.loads(line))
    decisions,groups,totals=build_alert_presentation(alerts,settings,runtime,meta)
    request=read_json(folder/"richiesta.json") if (folder/"richiesta.json").exists() else {}
    totals["collection_status"] = summary["status"]
    totals["unreadable_records"] = summary.get("remote",{}).get("malformed_lines",0)
    lines=render_alert_presentation(groups,totals,request)
    write_json(folder/"criteri_presentazione.json",settings)
    write_json(folder/"riepilogo_presentazione.json",totals)
    write_json(folder/"gruppi_presentazione.json",groups)
    with (folder/"selezione_presentazione.jsonl").open("w",encoding="utf-8",newline="\n") as out:
        for row in decisions:out.write(json.dumps(row,ensure_ascii=False)+"\n")
    (folder/"presentazione_alert.txt").write_text("\n".join(t for t,c in lines)+"\n",encoding="utf-8-sig")
    color=settings["color"] and enable_console_vt()
    for text,tone in lines:
        prefix={"red":"\x1b[91m","yellow":"\x1b[93m"}.get(tone,"") if color else ""
        print(prefix+text+("\x1b[0m" if prefix else ""))


def monitor_panel(mon,elapsed):
    seconds=max(0,int(elapsed));hours,seconds=divmod(seconds,3600);minutes,seconds=divmod(seconds,60)
    rows=list(mon.coverage.values())
    both=sum(all(r["sensors"][s]["completed"]>0 for s in mon.modes) for r in rows)
    phase="CONTROLLO INIZIALE" if mon.phase=="BASELINE" else "OSSERVAZIONE"
    lines=["SESSIONE WINDOWS-HR — MONITORAGGIO ATTIVO",str(mon.session),"",
        "Fase: "+phase, f"Durata sessione:                 {hours:02}:{minutes:02}:{seconds:02}"]
    if mon.phase=="BASELINE":
        lines.append("Tenere il RAT fermo. Controllo iniziale residuo: %d s" % max(0,mon.cfg["baseline_seconds"]-elapsed))
    else:lines.append("Controllo iniziale terminato; usare MARCA Inizio RAT quando opportuno.")
    for kind in mon.modes:
        counts=mon.sensor_counts[kind]
        lines.append(f"{kind}: {counts['SCAN_COMPLETED']} scansioni completate | {counts['SCAN_PARTIAL_OR_ERROR']} parziali/errori")
    lines.extend([f"Processi osservati:              {len(rows)}",
        f"Processi analizzati da tutti i sensori: {both}",
        f"Scansioni in coda: {len(mon.pending)} | In corso: {len(mon.running)}","",
        "Ultima scansione completata: "+getattr(mon,"last_completed_display","nessuna"),
        "Ultima marca: "+getattr(mon,"last_marker_display","nessuna"),"",
        "Comandi: STATO | MARCA testo | STOP (Invio)","> "+mon.command_buffer])
    return "\n".join(console_text(x) for x in lines)



def main(argv=None):
    parser = argparse.ArgumentParser(description="Monitoraggio PE-sieve e Moneta su Windows-HR + esportazione alert Wazuh")
    parser.add_argument("mode", choices=["init", "monitor", "export"], nargs="?")
    parser.add_argument("--config", default=str(Path(__file__).with_name("config_hr.json")))
    parser.add_argument("--session", help="Cartella sessione, obbligatoria per export")
    parser.add_argument("--start", help="Inizio ISO 8601 con fuso")
    parser.add_argument("--end", help="Fine ISO 8601 con fuso")
    parser.add_argument("--yes", action="store_true", help="Conferma gli orari senza prompt; credenziali richieste se assenti")
    parser.add_argument("--no-export", action="store_true", help="Solo monitoraggio; esportazione rinviata")
    args = parser.parse_args(argv)
    if not args.mode:
        answer = input("1 Monitoraggio + esportazione\n2 Sola esportazione\n3 Esci\nScelta: ").strip()
        args.mode = {"1": "monitor", "2": "export"}.get(answer)
        if not args.mode:
            return 0
    if args.mode == "init":
        if Path(args.config).exists():
            raise FileExistsError("Configurazione gia presente; non sovrascritta")
        write_json(args.config, DEFAULT)
        print("Configurazione creata:", args.config); return 0
    cfg = load_config(args.config)
    if args.mode == "monitor":
        session, meta = monitor_session(cfg)
        if args.no_export:
            print("Monitoraggio salvato. Esportabile successivamente con modalita export."); return 0
        if not args.yes and input("Esportare ora gli alert? [s/N]: ").strip().lower() != "s":
            return 0
    else:
        session = Path(args.session or input("Cartella della sessione: ").strip()).resolve()
        meta = read_json(session / "session.json")
    start, end = ask_window(meta, args)
    folder = export_alerts(cfg, session, start, end)
    return 2 if read_json(folder / "riepilogo.json").get("status") == "PARTIAL" else 0


if __name__ == "__main__":
    try:
        sys.exit(main())
    except KeyboardInterrupt:
        print("\nOperazione interrotta; i dati locali restano disponibili.", file=sys.stderr)
        sys.exit(130)
    except Exception as exc:
        print("ERRORE: " + str(exc), file=sys.stderr)
        sys.exit(1)
